@dfalbel with the newly implemented module tracing features we probably don't need the old (hacky?) way of doing things, and i'm not sure if they were working with an official release anyway, so feel free to close as you see fit, but here's the reprex anyway:

```
test_module <- nn_module(
    initialize = function() {
        self$linear <- nn_linear(10, 10)
        self$norm <- nn_batch_norm1d(10)
        self$par <- nn_parameter(torch_tensor(2))
        self$buff <- nn_buffer(torch_randn(10, 5))
        self$constant <- 1
        self$hello <- list(torch_tensor(1), torch_tensor(2), "hello")
    },
    forward = function(x) {
        self$par * x
    },
    testing = function(x) {
        x %>%
            self$linear()
    },
    test_constant = function(x) {
        x + self$constant + self$hello[[2]]
    }
)

mod <- test_module()

for (p in mod$parameters) {
    p$detach_()
}

trfn <- function(x) mod(x)
m <- jit_trace(trfn, torch_randn(1))

m(torch_randn(1))
#   torch_tensor
#    0.1010
# [ CPUFloatType{1} ]
jit_save(m, "tracedfn.pt")

m <- jit_load("tracedfn.pt")
m
# An `nn_module` containing 0 parameters.
```

