I'm trying to optimize a optimize a tensor in some sort map reduce approach using torch in R.  In the code below is a schematic of the for loop implementation, but ideally i'd be able to run these in batches of S rather than one sample at a time.  Is there a way currently to implement this with torch? A naive approach might be to create some sort of dataset object. 

```
optimize_theta <- function(T0, covs, eta, Sigma, K, S, count_matrix,mu, learning_rate=0.2){
  nu = torch_empty(c(S,K-1, K-1), device=device)
  theta = torch_empty(c(K,S), device=device)
  T_tmp = T0toT(T0)
  f = covs_to_F(covs$bt, covs$br, covs$epi, covs$nuc, covs$clu)
  T_tensor = T_tmp$mul(f$unsqueeze(-2))
  for (s in 1:S){
    ## parallelize code by samples to reduce estimation variance
    old_loss = 1e11
    eta_s = eta[,s]
    mu_s = mu[,s]
    Y_d = count_matrix[,,,,,,s]
    MODEL = estimate_theta(eta_s, Sigma, mu_s, K, S, Y_d, T_tensor)
    optimizer = optim_adam(MODEL$parameters, lr = learning_rate)
    it=0
    not_converged =TRUE
    while (not_converged == TRUE && it != 1000){
      it = it+1
      theta_est = MODEL()
      optimizer$zero_grad()
      new_loss = theta_est
      new_loss$backward()
      optimizer$step()
      
      # if (it %% 100 == 0 || it==1){
      #   cat("Theta Step:",it,":", as.numeric(new_loss$item()), "\n")
      # }
      
      if(abs(new_loss$item() - old_loss)/old_loss < 1e-2){
        not_converged = FALSE
      } else {
        old_loss = new_loss$item()
      }
    }
    eta[,s] = MODEL$parameters$eta_s$detach()
    nu[s] = calc_hessInv(K, S, eta[,s], T_tensor, Y_d, MODEL$Sigma_inv$detach())
    theta[,s] = nnf_softmax(torch_cat(c(eta[,s], torch_zeros(1, device=device)),dim=1), dim=1)

  }
      
  return(list(eta=eta, nu = nu, theta = theta))
}
```

